mapper.sql:
SELECT r.id, r.menu_id, r.title, r.status, r.revision, r.author_id,
  r.assigned_reviewer_id, r.created_at, r.updated_at FROM requirement_entry r

  (r.status <> 'DRAFT' OR r.author_id = #{actorId})
  AND r.title LIKE #{pattern} ESCAPE '\'
  AND r.menu_id = #{menuId}
  AND r.status = #{status}
  AND r.author_id = #{authorId}
  AND r.screen_version_id = #{screenVersionId}

mapper.select:
WITH visible AS (), comment_totals AS ( SELECT c.requirement_id, COUNT(*) AS comment_count, MAX(c.created_at) AS last_comment_at FROM requirement_comment c INNER JOIN visible v ON v.id = c.requirement_id GROUP BY c.requirement_id ), history_totals AS ( SELECT h.requirement_id, COUNT(*) AS history_count FROM requirement_history h INNER JOIN visible v ON v.id = h.requirement_id GROUP BY h.requirement_id ) SELECT r.id, r.menu_id, m.name AS menu_name, r.title, r.status, r.revision, r.author_id, a.display_name AS author_name, r.assigned_reviewer_id, assigned.display_name AS assigned_reviewer_name, r.created_at, r.updated_at, review.decision AS review_decision, COALESCE(c.comment_count, 0) AS comment_count, COALESCE(h.history_count, 0) AS history_count, c.last_comment_at FROM visible r INNER JOIN menu_entry m ON m.id = r.menu_id INNER JOIN reference_user a ON a.id = r.author_id LEFT JOIN reference_user assigned ON assigned.id = r.assigned_reviewer_id LEFT JOIN requirement_review review ON review.requirement_id = r.id LEFT JOIN comment_totals c ON c.requirement_id = r.id LEFT JOIN history_totals h ON h.requirement_id = r.id ORDER BY
r.title COALESCE(c.comment_count, 0) COALESCE(h.history_count, 0) c.last_comment_at r.updated_at
ASCDESC NULLS LAST, r.id DESC LIMIT #{size} OFFSET #{offset}
